{# Phiếu Kỹ thuật Sản phẩm - A4. Sau khi sửa file này chạy: python scripts/build_print_format.py #}
{%- set grade = frappe.get_doc("SP Board Grade", doc.board_grade) if doc.board_grade else None -%}
<style>
	.sp-wrap { font-family: Arial, sans-serif; font-size: 9.5pt; color: #111; padding-bottom: 24px; }
	.sp-wrap table { width: 100%; border-collapse: collapse; margin-bottom: 6px; }
	.sp-wrap th, .sp-wrap td { border: 1px solid #444; padding: 1.5px 5px; vertical-align: top; }
	.sp-wrap th { background: #eee; text-align: left; width: 22%; font-weight: 600; }
	.sp-wrap td.num { text-align: right; }
	.sp-wrap h1 { text-align: center; font-size: 15pt; margin: 2px 0 2px; }
	.sp-wrap h3 { font-size: 10.5pt; margin: 6px 0 2px; text-transform: uppercase; }
	.sp-wrap .meta { text-align: center; margin-bottom: 8px; }
	.sp-wrap .sign { page-break-inside: avoid; }
	.sp-wrap .sign td { height: 46px; text-align: center; vertical-align: bottom; }
	.sp-wrap .foot { position: fixed; bottom: 0; left: 0; right: 0; font-size: 8.5pt; color: #444; border-top: 1px solid #444; padding-top: 3px; }
</style>
<div class="sp-wrap">
	<h1>PHIẾU KỸ THUẬT SẢN PHẨM</h1>
	<div class="meta">Mã spec: <b>{{ doc.spec_code }}</b> &nbsp;|&nbsp; Phiên bản: <b>R{{ doc.revision }}</b> &nbsp;|&nbsp; Trạng thái: <b>{{ doc.spec_status }}</b></div>

	<h3>1. Thông tin chung</h3>
	<table>
		<tr><th>Khách hàng</th><td>{{ doc.customer }}</td><th>Mã hàng của khách</th><td>{{ doc.customer_item_code or "" }}</td></tr>
		<tr><th>Tên sản phẩm</th><td>{{ doc.item_name }}</td><th>Item ERPNext</th><td>{{ doc.erpnext_item or "" }}</td></tr>
		<tr><th>Kiểu hộp</th><td>{{ doc.box_style }}</td><th>Mối nối</th><td>{{ doc.joint_type }}</td></tr>
	</table>

	<h3>2. Kết cấu giấy</h3>
	<table>
		<tr><th>Số lớp / Loại sóng</th><td>{{ doc.ply }} lớp / sóng {{ doc.flute }}</td><th>Kết cấu</th><td>{{ doc.board_grade }}</td></tr>
	</table>
	{% if grade %}
	<table>
		<tr><th style="width:10%">Lớp</th><th>Vai trò</th><th>Mã giấy</th><th style="width:15%">gsm</th></tr>
		{% for row in grade.layers %}
		<tr><td>{{ row.layer_no }}</td><td>{{ row.layer_role }}</td><td>{{ row.paper }}</td><td class="num">{{ row.gsm }}</td></tr>
		{% endfor %}
	</table>
	{% endif %}

	<h3>3. Kích thước (mm)</h3>
	<table>
		<tr><th>Kích thước trong (D x R x C)</th><td>{{ doc.inner_l }} x {{ doc.inner_w }} x {{ doc.inner_h }}</td>
			<th>Khổ phôi (D x R)</th><td>{{ "%.1f"|format(doc.blank_l or 0) }} x {{ "%.1f"|format(doc.blank_w or 0) }}</td></tr>
		<tr><th>Diện tích phôi</th><td colspan="3">{{ "%.4f"|format(doc.area_per_box_m2 or 0) }} m²/thùng</td></tr>
	</table>

	<h3>4. In ấn</h3>
	<table>
		<tr><th>Phương pháp in</th><td>{{ doc.print_method }}</td><th>Số màu</th><td>{{ doc.color_count or 0 }}</td></tr>
		<tr><th>Khuôn bế</th><td>{{ doc.cutting_die or "" }}</td><th>Bản in</th><td>{{ doc.printing_plate or "" }}</td></tr>
	</table>
	{% if doc.colors %}
	<table>
		<tr><th style="width:8%">STT</th><th>Mã mực</th><th>Pantone</th><th>Độ phủ (%)</th><th>Mặt in</th></tr>
		{% for c in doc.colors %}
		<tr><td>{{ loop.index }}</td><td>{{ c.ink_code }}</td><td>{{ c.pantone or "" }}</td><td class="num">{{ c.coverage_percent }}</td><td>{{ c.print_side }}</td></tr>
		{% endfor %}
	</table>
	{% endif %}

	<h3>5. Quy trình công đoạn</h3>
	<table>
		<tr><th style="width:8%">STT</th><th>Công đoạn</th><th>Ghi chú</th></tr>
		{% for op in doc.operations %}
		<tr><td>{{ op.seq }}</td><td>{{ op.operation }}</td><td>{{ op.note or "" }}</td></tr>
		{% else %}
		<tr><td colspan="3">&nbsp;</td></tr>
		{% endfor %}
	</table>

	<h3>6. Yêu cầu chất lượng và quy cách đóng gói</h3>
	<table>
		<tr><th>ECT tối thiểu</th><td>{{ doc.ect_min or "" }} kN/m</td><th>BCT tối thiểu</th><td>{{ doc.bct_min or "" }} N</td></tr>
		<tr><th>Bục tối thiểu</th><td>{{ doc.burst_min or "" }} kPa</td><th>Độ ẩm tối đa</th><td>{{ doc.moisture_max or "" }} %</td></tr>
		<tr><th>FSC</th><td>{{ doc.fsc_claim }}</td><th>Số thùng / bó</th><td>{{ doc.qty_per_bundle or "" }}</td></tr>
		<tr><th>Số bó / pallet</th><td>{{ doc.bundles_per_pallet or "" }}</td><th>Duyệt mẫu</th><td>{{ frappe.utils.formatdate(doc.approved_sample_date, "dd/mm/yyyy") if doc.approved_sample_date else "" }} {{ doc.approved_by or "" }}</td></tr>
	</table>

	<table class="sign">
		<tr><th style="text-align:center">Lập</th><th style="text-align:center">Kiểm tra</th><th style="text-align:center">Duyệt</th></tr>
		<tr><td>{{ doc.owner }}</td><td>&nbsp;</td><td>{{ doc.approved_by or "" }}</td></tr>
	</table>

	<div class="foot">Mã tài liệu: {{ doc.spec_code }} - Rev {{ doc.revision }} &nbsp;|&nbsp; In ngày {{ frappe.utils.formatdate(frappe.utils.today(), "dd/mm/yyyy") }}</div>
</div>
